
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Mexico_City'}).format(new Date());
const seed={jobs:[],aids:[
{id:'a1',institution:'Secretaría de Trabajo CDMX',title:'Seguro de Desempleo',category:'Económico',requirements:'Revisar convocatoria vigente y elegibilidad personal en el portal oficial.',missing:'Por determinar al revisar los requisitos',deadline:'',review:'2026-11-05',reminder:'',url:'https://tramites.cdmx.gob.mx/desempleo/',status:'Por investigar',verified:'Por verificar',priority:'Alta',next:'Confirmar convocatoria abierta, requisitos y documentos. La existencia del portal está consultada; la elegibilidad no está confirmada.'},
{id:'a2',institution:'FONDESO',title:'Financiamiento para emprendimiento',category:'Emprendimiento',requirements:'Consultar producto vigente, costos, capacitación y condiciones. Es financiamiento; verificar obligaciones de pago.',missing:'Por determinar',deadline:'',review:'2026-11-05',reminder:'',url:'https://www.tramites.cdmx.gob.mx/fondeso/',status:'Por investigar',verified:'Por verificar',priority:'Media',next:'Validar convocatoria y condiciones actuales en la fuente oficial.'},
{id:'a3',institution:'Secretaría de Salud Pública CDMX',title:'Orientación sobre atención pública de salud',category:'Salud',requirements:'Confirmar institución, unidad de atención y requisitos actuales según situación de seguridad social.',missing:'Por determinar',deadline:'',review:'',reminder:'',url:'https://www.salud.cdmx.gob.mx/',status:'Por investigar',verified:'Por verificar',priority:'Media',next:'Consultar canal oficial para identificar servicio y unidad aplicable.'}
],templates:[
{id:'t1',title:'CV adaptado',body:'PERFIL\nProfesional de [área] con experiencia comprobable en [habilidades relevantes].\n\nEXPERIENCIA RELEVANTE\n[Proyecto o puesto] · [Fechas]\n• [Acción realizada] con [herramienta], logrando [resultado verificable].\n\nHABILIDADES\n[Seleccionar marketing, diseño, desarrollo web e IA que realmente dominas].\n\nAntes de usar: ajustar palabras clave a la vacante, comprobar fechas y no inventar métricas.'},
{id:'t2',title:'Portafolio por oportunidad',body:'Selección para [puesto] en [empresa]\n\n1. [Caso relevante de marketing/diseño/web/IA]\nProblema: [contexto]\nMi contribución: [responsabilidad real]\nProceso y herramientas: [detalle]\nResultado: [evidencia verificable]\nEnlace: [URL]\n\nRepetir con 2–3 proyectos. Comprobar permisos para compartir materiales.'},
{id:'t3',title:'Mensaje de postulación',body:'Hola, equipo de [empresa]:\n\nMe interesa la posición de [puesto]. Mi experiencia en [habilidad relevante] se refleja en [proyecto concreto y resultado verificable].\n\nComparto mi CV y una selección de proyectos: [enlace]. Me gustaría conversar sobre cómo puedo contribuir a [necesidad del puesto].\n\nGracias por su tiempo,\n[nombre]\n[contacto]'}
]};
let data;try{data=JSON.parse(localStorage.getItem('rumbo-v1'))||structuredClone(seed)}catch{data=structuredClone(seed)}
let page='Resumen',query='',filter='Todos',verification='Todos',sort='priority',chosen=new Set();
const pages=['Resumen','Oportunidades','Apoyos CDMX','Comparar','Pendientes','Plantillas'];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function save(){try{localStorage.setItem('rumbo-v1',JSON.stringify(data))}catch{toast('No se pudo guardar. Exporta un respaldo.');return false}return true}
function badge(v){return '<span class="tag '+(v==='Confirmada'?'':'amber')+'">'+esc(v)+'</span>'}
function link(u){try{const x=new URL(u);if(!['http:','https:'].includes(x.protocol))return '';return '<a href="'+esc(x.href)+'" target="_blank" rel="noopener noreferrer">Abrir fuente ↗</a>'}catch{return 'Sin enlace'}}
function go(p){page=p;query='';filter='Todos';verification='Todos';render()}
function hero(title,sub,button=''){return '<section class="hero"><div><div class="eyebrow">CONSTRUYE TU SIGUIENTE PASO</div><h1>'+title+'</h1><p>'+sub+'</p></div>'+button+'</section>'}
function active(r){return !['Descartada','Cerrada','Concluido','No elegible'].includes(r.status)}
function all(){return [...data.jobs.map(r=>({...r,kind:'jobs'})),...data.aids.map(r=>({...r,kind:'aids'}))]}
const priority={Alta:0,Media:1,Baja:2};
function rows(list){return list.map(r=>'<div class="row"><span class="icon">'+(r.kind==='jobs'?'↗':'◇')+'</span><div><h3>'+esc(r.title)+'</h3><p>'+esc(r.next||'Define tu siguiente paso')+'</p><small>'+esc(r.reminder||'Sin recordatorio')+' · '+esc(r.priority)+'</small></div><button onclick="edit(\''+r.kind+'\',\''+r.id+'\')">Revisar</button></div>').join('')||'<div class="empty">Sin pendientes en esta vista.</div>'}
function render(){ $('#nav').innerHTML=pages.map((p,i)=>'<button class="'+(page===p?'active':'')+'" onclick="go(\''+p+'\')">'+['◫','↗','◇','⇄','☑','▤'][i]+' &nbsp; '+p+'</button>').join('');
const pending=all().filter(active).sort((a,b)=>(a.reminder||'9999').localeCompare(b.reminder||'9999')||priority[a.priority]-priority[b.priority]);
if(page==='Resumen')$('#app').innerHTML=hero('Tu próximo capítulo empieza aquí.','Organiza tus opciones. Da seguimiento. Avanza a tu ritmo.','<button class="primary" onclick="edit(\'jobs\')">＋ Nueva oportunidad</button>')+
'<div class="stats">'+[['Oportunidades',data.jobs.length,'En tu búsqueda'],['Apoyos por explorar',data.aids.filter(active).length,'Economía, salud y emprendimiento'],['Por verificar',all().filter(r=>r.verified!=='Confirmada').length,'Revisa la fuente oficial'],['Recordatorios de hoy',pending.filter(r=>r.reminder&&r.reminder<=today()).length,'Incluye vencidos']].map(x=>'<div class="stat">'+x[0]+'<strong>'+x[1]+'</strong><small>'+x[2]+'</small></div>').join('')+'</div><div class="grid"><section class="panel"><div class="panelhead"><h2>Lo siguiente en tu lista</h2><button onclick="go(\'Pendientes\')">Ver todo ↗</button></div>'+rows(pending.slice(0,4))+'</section><section class="panel"><span class="eyebrow">TU PERFIL, TU VENTAJA</span><h2>Una experiencia que conecta.</h2><p>Marketing, diseño, desarrollo web y herramientas de IA.</p><div class="tag">Marketing</div> <div class="tag">Diseño</div> <div class="tag">Web</div> <div class="tag">IA</div><p>Valora cada habilidad de 0 a 100 al revisar una vacante. El promedio será una referencia personal de compatibilidad.</p><button onclick="go(\'Plantillas\')">Preparar mi postulación ↗</button></section></div><div class="notice">Datos guardados únicamente en este navegador. Exporta un respaldo para conservarlos o trasladarlos. Los recordatorios aparecen aquí al abrir el Site; no se envían notificaciones externas.</div>';
else if(['Oportunidades','Apoyos CDMX'].includes(page))listPage(page==='Oportunidades'?'jobs':'aids');
else if(page==='Pendientes')$('#app').innerHTML=hero('Un paso a la vez.','Próximas acciones de empleo y apoyos, juntas en tu agenda.')+'<div class="toolbar"><button onclick="showPending(\'all\')">Todos</button><button onclick="showPending(\'due\')">Hoy y vencidos</button><button onclick="showPending(\'verify\')">Por verificar</button><button onclick="showPending(\'docs\')">Documentos pendientes</button></div><section class="panel" id="pending">'+rows(pending)+'</section>';
else if(page==='Comparar'){const list=data.jobs.filter(r=>chosen.has(r.id));$('#app').innerHTML=hero('Compara con perspectiva.','Selecciona hasta cuatro vacantes en Oportunidades.')+(list.length?'<div class="tablewrap"><table><tr><th>Criterio</th>'+list.map(r=>'<th>'+esc(r.title)+'<br>'+esc(r.company)+'</th>').join('')+'</tr>'+['mode','location','salary','priority','score','gaps','verified','next'].map((k,i)=>'<tr><th>'+['Modalidad','Ubicación','Sueldo / condiciones','Prioridad','Compatibilidad','Brechas','Verificación','Próximo paso'][i]+'</th>'+list.map(r=>'<td>'+esc(r[k]||'Por verificar')+(k==='score'?'%':'')+'</td>').join('')+'</tr>').join('')+'</table></div>':'<div class="panel empty">Selecciona vacantes para construir tu comparación.<br><button onclick="go(\'Oportunidades\')">Ir a oportunidades</button></div>')}
else templates();
}
function showPending(type){$('#pending').innerHTML=rows(all().filter(active).filter(r=>type==='all'||type==='due'&&r.reminder&&r.reminder<=today()||type==='verify'&&r.verified!=='Confirmada'||type==='docs'&&r.kind==='aids'&&r.missing).sort((a,b)=>(a.reminder||'9999').localeCompare(b.reminder||'9999')))}
function listPage(kind){const jobs=kind==='jobs';$('#app').innerHTML=hero(jobs?'Oportunidades con dirección.':'Apoyos para seguir adelante.',jobs?'Encuentra el lugar donde tus habilidades pueden hacer la diferencia.':'Economía, salud y emprendimiento en Ciudad de México.','<button class="primary" onclick="edit(\''+kind+'\')">＋ '+(jobs?'Nueva oportunidad':'Nuevo apoyo')+'</button>')+(jobs?'<div class="notice">Tu panel inicia sin vacantes inventadas. Agrega enlaces reales y registra la fecha en que revisas cada oferta.</div>':'<div class="notice">Puntos de partida oficiales, consultados el 5 de noviembre de 2026. Convocatorias, fechas y elegibilidad personal siguen por verificar. No se presupone que cumplas requisitos.</div>')+'<div class="toolbar"><input aria-label="Buscar" id="search" type="search" placeholder="Buscar empresa, puesto, institución..." value="'+esc(query)+'"><select aria-label="Estado" id="state"><option>Todos</option>'+[...new Set(data[kind].map(r=>r.status))].map(v=>'<option '+(filter===v?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select><select aria-label="Verificación" id="verify">'+['Todos','Confirmada','Por verificar'].map(v=>'<option '+(verification===v?'selected':'')+'>'+v+'</option>').join('')+'</select><select id="sort" aria-label="Ordenar"><option value="priority">Prioridad</option><option value="score">Compatibilidad</option><option value="reminder">Recordatorio</option></select></div><div id="results"></div>';$('#search').oninput=e=>{query=e.target.value;results(kind)};$('#state').onchange=e=>{filter=e.target.value;results(kind)};$('#verify').onchange=e=>{verification=e.target.value;results(kind)};$('#sort').value=sort;$('#sort').onchange=e=>{sort=e.target.value;results(kind)};results(kind)}
function results(kind){const jobs=kind==='jobs';const list=data[kind].filter(r=>JSON.stringify(r).toLowerCase().includes(query.toLowerCase())&&(filter==='Todos'||r.status===filter)&&(verification==='Todos'||r.verified===verification)).sort((a,b)=>sort==='score'?(b.score||0)-(a.score||0):sort==='reminder'?(a.reminder||'9999').localeCompare(b.reminder||'9999'):priority[a.priority]-priority[b.priority]);
$('#results').innerHTML=list.length?'<div class="tablewrap"><table><thead><tr>'+(jobs?'<th>Comparar</th>':'')+'<th>'+(jobs?'Empresa / puesto':'Institución / programa')+'</th><th>'+(jobs?'Modalidad / ubicación':'Tipo / requisitos')+'</th><th>'+(jobs?'Compatibilidad':'Documentos faltantes')+'</th><th>'+(jobs?'Brechas':'Fechas')+'</th><th>Estado / prioridad</th><th>Fuente / revisión</th><th>Próximo paso</th><th></th></tr></thead><tbody>'+list.map(r=>'<tr>'+(jobs?'<td><input type="checkbox" aria-label="Comparar '+esc(r.title)+'" '+(chosen.has(r.id)?'checked':'')+' onchange="choose(\''+r.id+'\',this)"></td>':'')+'<td><h3>'+esc(r.title)+'</h3><small>'+esc(jobs?r.company:r.institution)+'</small></td><td>'+esc(jobs?r.mode:r.category)+'<small>'+esc(jobs?r.location:r.requirements)+'</small></td><td>'+(jobs?'<span class="score">'+r.score+'%</span><small>M '+r.marketing+' · D '+r.design+' · Web '+r.web+' · IA '+r.ai+'</small>':esc(r.missing||'Sin registrar'))+'</td><td>'+esc(jobs?r.gaps:'Cierre: '+(r.deadline||'Por verificar'))+'<small>Recordar: '+esc(r.reminder||'Sin fecha')+'</small></td><td><span class="tag blue">'+esc(r.status)+'</span><small>'+esc(r.priority)+'</small></td><td>'+link(r.url)+'<small>'+esc(r.review||'Sin revisión')+'</small>'+badge(r.verified)+'</td><td>'+esc(r.next)+'</td><td><button onclick="edit(\''+kind+'\',\''+r.id+'\')">Editar</button></td></tr>').join('')+'</tbody></table></div>':'<div class="panel empty">No hay registros para esta vista.<br><button onclick="edit(\''+kind+'\')">＋ Agregar registro</button></div>'}
function choose(id,box){if(box.checked&&chosen.size>=4){box.checked=false;toast('Puedes comparar hasta cuatro vacantes.');return}box.checked?chosen.add(id):chosen.delete(id)}
const common=[['priority','Prioridad',['Alta','Media','Baja']],['verified','Verificación',['Por verificar','Confirmada']],['review','Fecha de revisión','date'],['reminder','Recordatorio','date'],['url','Enlace oficial o de la vacante','url'],['next','Próximos pasos','textarea']];
const fieldsJobs=[['company','Empresa','text'],['title','Puesto','text'],['mode','Modalidad',['Por verificar','Remota','Híbrida','Presencial']],['location','Ubicación','text'],['salary','Sueldo / condiciones','text'],['status','Estado',['Por revisar','Preparando','Postulada','Entrevista','Oferta','Descartada','Cerrada']],...['marketing','design','web','ai'].map((k,i)=>[k,['Marketing (0–100)','Diseño (0–100)','Desarrollo web (0–100)','Herramientas de IA (0–100)'][i],'number']),['gaps','Brechas y evidencia de compatibilidad','textarea'],...common];
const fieldsAids=[['institution','Institución','text'],['title','Programa','text'],['category','Tipo',['Económico','Salud','Emprendimiento']],['status','Estado',['Por investigar','Revisando requisitos','Preparando documentos','En trámite','Aprobado','No elegible','Concluido']],['requirements','Requisitos por confirmar / confirmados','textarea'],['missing','Documentos faltantes (solo lista; sin archivos sensibles)','textarea'],['deadline','Fecha límite (vacía si no confirmada)','date'],...common];
let editing;
function edit(kind,id){const r=data[kind].find(x=>x.id===id)||{priority:'Media',verified:'Por verificar',marketing:0,design:0,web:0,ai:0};editing={kind,id};$('#formtitle').textContent=id?'Editar registro':kind==='jobs'?'Nueva oportunidad':'Nuevo apoyo';$('#fields').innerHTML=(kind==='jobs'?fieldsJobs:fieldsAids).map(([k,label,type])=>'<label class="field '+(type==='textarea'?'wide':'')+'">'+label+(Array.isArray(type)?'<select name="'+k+'">'+type.map(v=>'<option '+(r[k]===v?'selected':'')+'>'+v+'</option>').join('')+'</select>':type==='textarea'?'<textarea name="'+k+'">'+esc(r[k])+'</textarea>':'<input name="'+k+'" type="'+type+'" '+(type==='number'?'min="0" max="100" ':'')+(k==='title'||k==='company'||k==='institution'?'required ':'')+' value="'+esc(r[k])+'">')+'</label>').join('')+(id?'<button type="button" class="danger" onclick="removeRecord()">Eliminar registro</button>':'');$('#editor').showModal()}
$('#form').onsubmit=e=>{e.preventDefault();const r=Object.fromEntries(new FormData(e.target));if(r.verified==='Confirmada'&&(!r.url||!r.review)){toast('Para confirmar, agrega fuente y fecha de revisión.');return}if(editing.kind==='jobs'){['marketing','design','web','ai'].forEach(k=>r[k]=Number(r[k]||0));r.score=Math.round((r.marketing+r.design+r.web+r.ai)/4)}r.id=editing.id||crypto.randomUUID();const list=data[editing.kind],i=list.findIndex(x=>x.id===r.id);i<0?list.push(r):list[i]=r;if(save()){editor.close();render();toast('Registro guardado')}};
function removeRecord(){if(confirm('¿Eliminar este registro?')){data[editing.kind]=data[editing.kind].filter(r=>r.id!==editing.id);chosen.delete(editing.id);save();editor.close();render()}}
function templates(){$('#app').innerHTML=hero('Tu experiencia, bien contada.','Reutiliza una base y adáptala a cada oportunidad. Tú revisas y envías.')+'<div class="cards">'+data.templates.map(t=>'<section class="card"><span class="tag">Plantilla reutilizable</span><h2>'+esc(t.title)+'</h2><textarea aria-label="'+esc(t.title)+'" class="template" id="'+t.id+'">'+esc(t.body)+'</textarea><footer><button onclick="copyTemplate(\''+t.id+'\')">Copiar</button><button class="primary" onclick="saveTemplate(\''+t.id+'\')">Guardar base</button></footer></section>').join('')+'</div><div class="notice">Sustituye los campos entre corchetes y revisa toda la información. No se envían solicitudes, correos ni mensajes automáticamente.</div>'}
function saveTemplate(id){data.templates.find(t=>t.id===id).body=$('#'+id).value;if(save())toast('Plantilla guardada')}
async function copyTemplate(id){try{await navigator.clipboard.writeText($('#'+id).value);toast('Texto copiado para adaptar')}catch{toast('Selecciona y copia el texto manualmente')}}
$('#backup').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='rumbo-respaldo-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
$('#restore').onchange=async e=>{try{const d=JSON.parse(await e.target.files[0].text());if(!Array.isArray(d.jobs)||!Array.isArray(d.aids)||!Array.isArray(d.templates)||!d.templates.every(t=>/^t[123]$/.test(t.id)&&typeof t.body==='string'))throw Error();if(![...d.jobs,...d.aids].every(r=>r&&typeof r.id==='string'&&/^[a-zA-Z0-9-]+$/.test(r.id)))throw Error();if(confirm('¿Reemplazar los registros actuales con este respaldo?')){data=d;chosen.clear();save();render();toast('Respaldo importado')}}catch{toast('El archivo no es un respaldo válido.')}e.target.value=''};
render();
